'use client'

import { useEffect, useState } from 'react'
import { motion, useMotionTemplate, useMotionValue } from 'motion/react'

function Tile({ className = '', title, body, children }) {
  const x = useMotionValue(-300), y = useMotionValue(-300)
  const bg = useMotionTemplate`radial-gradient(220px circle at ${x}px ${y}px, color-mix(in oklab, var(--acc) 10%, transparent), transparent 70%)`
  return (
    <div onPointerMove={(e) => { const r = e.currentTarget.getBoundingClientRect(); x.set(e.clientX - r.left); y.set(e.clientY - r.top) }} onPointerLeave={() => { x.set(-300); y.set(-300) }}
      className={`relative overflow-hidden rounded-2xl border border-line bg-panel ${className}`}>
      <motion.div className="pointer-events-none absolute inset-0" style={{ background: bg }} />
      <div className="relative flex h-full flex-col">
        <div className="relative min-h-36 flex-1">{children}</div>
        <div className="p-5 pt-0"><h3 className="text-[15px] font-medium text-tx">{title}</h3><p className="mt-1 text-sm text-mute">{body}</p></div>
      </div>
    </div>
  )
}

function Regions() {
  const [on, setOn] = useState(0)
  useEffect(() => { const id = setInterval(() => setOn((n) => (n + 1) % 12), 500); return () => clearInterval(id) }, [])
  return <div className="absolute inset-0 grid place-items-center p-6"><div className="grid grid-cols-6 gap-2">{Array.from({ length: 12 }, (_, i) => <motion.span key={i} animate={{ backgroundColor: i === on ? 'var(--acc)' : 'var(--line)', scale: i === on ? 1.1 : 1 }} className="size-7 rounded-md @3xl:size-8" />)}</div></div>
}
function Rollback() {
  const [v, setV] = useState(3)
  useEffect(() => { const id = setInterval(() => setV((n) => (n === 3 ? 2 : 3)), 1800); return () => clearInterval(id) }, [])
  return (
    <div className="absolute inset-0 flex items-center justify-center gap-2 p-6">
      {[1, 2, 3].map((n) => (
        <motion.div key={n} animate={{ opacity: n === v ? 1 : 0.35, y: n === v ? -6 : 0, borderColor: n === v ? 'var(--acc)' : 'var(--line2)' }} className="rounded-lg border bg-bg px-3 py-2 font-mono text-xs text-tx">v1.{n}</motion.div>
      ))}
    </div>
  )
}
function Logs() {
  const [lines, setLines] = useState([0, 1, 2, 3])
  useEffect(() => { const id = setInterval(() => setLines((l) => [...l.slice(1), l[l.length - 1] + 1]), 700); return () => clearInterval(id) }, [])
  const txt = ['GET /api/user 200 12ms', 'POST /checkout 201 48ms', 'GET / 304 3ms', 'GET /img/hero.webp 200 9ms', 'GET /api/search 200 21ms']
  return <div className="absolute inset-0 overflow-hidden p-5 font-mono text-[11px] text-mute">{lines.map((n) => <motion.div key={n} layout initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} className="py-0.5"><span className="text-faint">{String(10 + (n % 50)).padStart(2, '0')}:04</span> {txt[n % txt.length]}</motion.div>)}</div>
}
function Shield() {
  return (
    <div className="absolute inset-0 grid place-items-center">
      <motion.svg viewBox="0 0 24 24" className="size-16 text-acc" fill="none" stroke="currentColor" strokeWidth="1.2"><motion.path d="M12 3 4 6v6c0 5 3.5 8 8 9 4.5-1 8-4 8-9V6z" initial={{ pathLength: 0 }} animate={{ pathLength: 1 }} transition={{ duration: 1.6, repeat: Infinity, repeatType: 'reverse', repeatDelay: 0.6 }} /><path d="m9 12 2 2 4-4" /></motion.svg>
    </div>
  )
}

// Block: a four-tile feature section. Every tile has its own small live demo.
export default function FeatureBento() {
  return (
    <section className="@container w-full">
      <div className="grid gap-3 @3xl:grid-cols-3">
        <Tile className="@3xl:col-span-2" title="Runs in every region" body="Your code is copied to each edge location on deploy."><Regions /></Tile>
        <Tile title="Instant rollback" body="One click back to any previous build."><Rollback /></Tile>
        <Tile title="Built-in firewall" body="Bad traffic stops before it reaches you."><Shield /></Tile>
        <Tile className="@3xl:col-span-2" title="Real-time logs" body="Tail requests as they happen, no setup."><Logs /></Tile>
      </div>
    </section>
  )
}

'use client'

import { useState } from 'react'
import { motion, AnimatePresence } from 'motion/react'

const PLANS = [
  { n: 'Solo', m: 12, y: 9, f: ['1 workspace', '5 GB'] },
  { n: 'Team', m: 29, y: 23, f: ['Unlimited workspaces', '100 GB', 'Roles'], hot: true },
]

export default function PricingMorph({ plans = PLANS, currency = '$' }) {
  const [yearly, setYearly] = useState(false)
  return (
    <div className="w-full max-w-md">
      <div className="mx-auto mb-5 flex w-fit rounded-full border border-line2 bg-panel p-1 text-xs">
        {['Monthly', 'Yearly'].map((l, i) => (
          <button key={l} onClick={() => setYearly(!!i)} className="relative px-4 py-1.5">
            {yearly === !!i && <motion.span layoutId="pm-pill" className="absolute inset-0 rounded-full bg-tx" transition={{ type: 'spring', stiffness: 420, damping: 32 }} />}
            <span className={`relative ${yearly === !!i ? 'text-bg' : 'text-mute'}`}>{l}</span>
          </button>
        ))}
      </div>
      <div className="grid grid-cols-2 gap-2">
        {plans.map((p) => (
          <motion.div layout key={p.n} transition={{ type: 'spring', stiffness: 300, damping: 28 }} className={`min-w-0 rounded-2xl border p-4 ${p.hot ? 'border-acc/50 bg-panel2' : 'border-line bg-panel'}`}>
            <div className="text-sm text-mute">{p.n}</div>
            <div className="mt-2 flex min-w-0 flex-wrap items-baseline gap-x-1">
              <span className="min-w-0 break-all text-mute">{currency}</span>
              <AnimatePresence mode="popLayout" initial={false}>
                <motion.span key={yearly ? p.y : p.m} initial={{ y: 16, opacity: 0, filter: 'blur(4px)' }} animate={{ y: 0, opacity: 1, filter: 'blur(0px)' }} exit={{ y: -16, opacity: 0, filter: 'blur(4px)' }} transition={{ type: 'spring', stiffness: 400, damping: 28 }} className="text-3xl font-medium text-tx">
                  {yearly ? p.y : p.m}
                </motion.span>
              </AnimatePresence>
              <span className="text-xs text-faint">/mo</span>
            </div>
            <AnimatePresence>
              {yearly && <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }} className="overflow-hidden break-words text-xs text-acc">billed {currency}{p.y * 12} yearly</motion.div>}
            </AnimatePresence>
            <ul className="mt-3 space-y-1 break-words text-xs text-mute">{p.f.map((f) => <li key={f}>· {f}</li>)}</ul>
          </motion.div>
        ))}
      </div>
    </div>
  )
}

'use client'

import { useState } from 'react'
import { motion, AnimatePresence } from 'motion/react'

const QA = [
  ['Is there a free tier?', 'Yes. Hobby projects run free with generous limits. You only pay when you add a team.'],
  ['Can I use my own domain?', 'Point a CNAME at us and SSL is issued in about a minute.'],
  ['Where does my code run?', 'In every edge location we have. Requests go to the nearest one.'],
  ['How do rollbacks work?', 'Every deploy is kept. Pick one and it goes live instantly.'],
]

// Block: FAQ with one open item at a time and a plus that turns into a minus.
export default function FaqAccordion({ items = QA, title = 'Questions' }) {
  const [open, setOpen] = useState(0)
  return (
    <section className="@container w-full rounded-2xl border border-line bg-bg p-6 @3xl:grid @3xl:grid-cols-[220px_1fr] @3xl:gap-10 @3xl:p-10">
      <h2 className="text-2xl font-semibold tracking-tight text-tx">{title}</h2>
      <div className="mt-6 divide-y divide-line @3xl:mt-0">
        {items.map(([q, a], i) => (
          <div key={q}>
            <button type="button" onClick={() => setOpen(open === i ? -1 : i)} aria-expanded={open === i} className="flex w-full items-center justify-between gap-4 py-4 text-left text-[15px] text-tx">
              {q}
              <span className="relative size-3.5 shrink-0">
                <span className="absolute inset-x-0 top-1/2 h-px bg-mute" />
                <motion.span className="absolute inset-y-0 left-1/2 w-px bg-mute" animate={{ scaleY: open === i ? 0 : 1 }} />
              </span>
            </button>
            <AnimatePresence initial={false}>
              {open === i && (
                <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }} transition={{ type: 'spring', stiffness: 320, damping: 34 }} className="overflow-hidden">
                  <p className="pb-4 text-sm leading-6 text-mute">{a}</p>
                </motion.div>
              )}
            </AnimatePresence>
          </div>
        ))}
      </div>
    </section>
  )
}

'use client'

import { useEffect, useRef } from 'react'
import { worldDots } from './world-dots'

// Light or dark, read from the --bg token itself: works with a .dark class, a .light class, or neither.
const isLightTheme = () => {
  const h = getComputedStyle(document.documentElement).getPropertyValue('--bg').trim().replace(/^#(.)(.)(.)$/, '#$1$1$2$2$3$3')
  return /^#[0-9a-f]{6}/i.test(h) ? [1, 3, 5].reduce((s, i, k) => s + parseInt(h.slice(i, i + 2), 16) * [0.299, 0.587, 0.114][k], 0) > 128 : !document.documentElement.classList.contains('dark')
}

const HUBS = [[19.07, 72.87], [50.11, 8.68], [38.95, -77.45], [1.35, 103.99], [-23.43, -46.47], [35.77, 140.39], [-33.94, 151.18], [25.25, 55.36]]
const rad = Math.PI / 180
const vec = (lat, lon) => [Math.cos(lat * rad) * Math.sin(lon * rad), Math.sin(lat * rad), Math.cos(lat * rad) * Math.cos(lon * rad)]
const slerp = (a, b, t) => {
  const d = Math.acos(Math.max(-1, Math.min(1, a[0] * b[0] + a[1] * b[1] + a[2] * b[2])))
  if (d < 1e-4) return a
  const s = Math.sin(d), k0 = Math.sin((1 - t) * d) / s, k1 = Math.sin(t * d) / s
  return [a[0] * k0 + b[0] * k1, a[1] * k0 + b[1] * k1, a[2] * k0 + b[2] * k1]
}

// Rotating dotted globe of real land masses with arcs between edge locations. Drag to spin.
export default function EdgeGlobe({ size = 320, hubs = HUBS, speed = 0.18, color = undefined }) {
  const ref = useRef(null)
  useEffect(() => {
    const c = ref.current
    const ctx = c?.getContext('2d')
    if (!ctx) return
    const d = Math.min(window.devicePixelRatio || 1, 2)
    c.width = size * d; c.height = size * d; ctx.setTransform(d, 0, 0, d, 0, 0)
    const pts = worldDots().map((p) => vec(p.lat, p.lon))
    const H = hubs.map(([la, lo]) => vec(la, lo))
    const arcs = Array.from({ length: Math.min(5, H.length) }, (_, i) => ({ a: i % H.length, b: (i * 3 + 2) % H.length, t: -i * 0.3 }))
    let rot = -1.3, raf, last = performance.now(), drag = null
    const R = size * 0.44, cx = size / 2, cy = size / 2, tilt = -0.3
    const proj = ([x, y, z], lift = 1) => {
      const X = x * Math.cos(rot) + z * Math.sin(rot), Z = -x * Math.sin(rot) + z * Math.cos(rot)
      const Y = y * Math.cos(tilt) - Z * Math.sin(tilt), Z2 = y * Math.sin(tilt) + Z * Math.cos(tilt)
      return [cx + X * R * lift, cy - Y * R * lift, Z2]
    }
    const draw = (now) => {
      const dt = Math.min(0.05, (now - last) / 1000); last = now
      if (!drag) rot += speed * dt
      ctx.clearRect(0, 0, size, size)
      const lite = isLightTheme()
      const ink = color || (lite ? '29,29,31' : '245,245,247')
      const g = ctx.createRadialGradient(cx - R * 0.3, cy - R * 0.3, R * 0.1, cx, cy, R)
      if (lite) { g.addColorStop(0, '#ffffff'); g.addColorStop(1, '#e8e8ec') } else { g.addColorStop(0, '#1c1c1e'); g.addColorStop(1, '#050505') }
      ctx.fillStyle = g; ctx.beginPath(); ctx.arc(cx, cy, R, 0, 6.283); ctx.fill()
      ctx.strokeStyle = lite ? 'rgba(20,20,23,0.16)' : 'rgba(237,237,239,0.08)'; ctx.stroke()
      for (const p of pts) {
        const [x, y, z] = proj(p)
        if (z < 0) continue
        ctx.fillStyle = lite ? `rgba(20,20,23,${0.14 + z * 0.5})` : `rgba(237,237,239,${0.1 + z * 0.45})`
        ctx.fillRect(x - 0.8, y - 0.8, 1.6, 1.6)
      }
      for (const arc of arcs) {
        arc.t += dt * 0.4
        if (arc.t > 1.4) { arc.t = 0; arc.a = arc.b; arc.b = (arc.b + 1 + ((Math.random() * (H.length - 1)) | 0)) % H.length }
        if (arc.t <= 0) continue
        const head = Math.min(1, arc.t), tail = Math.max(0, arc.t - 0.4)
        for (let i = 0; i < 20; i++) {
          const t0 = tail + ((head - tail) * i) / 20, t1 = tail + ((head - tail) * (i + 1)) / 20
          const l0 = 1 + Math.sin(t0 * Math.PI) * 0.18, l1 = 1 + Math.sin(t1 * Math.PI) * 0.18
          const p0 = proj(slerp(H[arc.a], H[arc.b], t0), l0), p1 = proj(slerp(H[arc.a], H[arc.b], t1), l1)
          if (p0[2] < -0.1 || p1[2] < -0.1) continue
          ctx.strokeStyle = `rgba(${ink},${(i / 20) * 0.95})`; ctx.lineWidth = 1.3
          ctx.beginPath(); ctx.moveTo(p0[0], p0[1]); ctx.lineTo(p1[0], p1[1]); ctx.stroke()
        }
      }
      const pulse = (now / 1600) % 1
      for (const h of H) {
        const [x, y, z] = proj(h)
        if (z < 0) continue
        ctx.strokeStyle = `rgba(${ink},${(1 - pulse) * 0.7 * z})`
        ctx.beginPath(); ctx.arc(x, y, 2 + pulse * 9, 0, 6.283); ctx.stroke()
        ctx.fillStyle = `rgb(${ink})`; ctx.beginPath(); ctx.arc(x, y, 2, 0, 6.283); ctx.fill()
      }
      raf = requestAnimationFrame(draw)
    }
    raf = requestAnimationFrame(draw)
    const down = (e) => { drag = e.clientX; c.setPointerCapture?.(e.pointerId) }
    const move = (e) => { if (drag !== null) { rot += (e.clientX - drag) * 0.008; drag = e.clientX } }
    const up = () => { drag = null }
    c.addEventListener('pointerdown', down); c.addEventListener('pointermove', move)
    c.addEventListener('pointerup', up); c.addEventListener('pointercancel', up)
    return () => {
      cancelAnimationFrame(raf)
      c.removeEventListener('pointerdown', down); c.removeEventListener('pointermove', move)
      c.removeEventListener('pointerup', up); c.removeEventListener('pointercancel', up)
    }
  }, [size, hubs, speed, color])
  return <canvas ref={ref} style={{ width: size, height: size }} className="cursor-grab touch-none active:cursor-grabbing" role="img" aria-label="Rotating globe" />
}

'use client'

import { motion } from 'motion/react'

const COLS = [
  ['Product', ['Pricing', 'Changelog', 'Status']],
  ['Company', ['About', 'Careers', 'Contact']],
  ['Legal', ['Privacy', 'Terms']],
]

// Block: site footer. Link columns, and a giant wordmark that rises in letter by letter.
export default function WordmarkFooter({ brand = 'acme', columns = COLS }) {
  return (
    <footer className="@container w-full overflow-hidden rounded-2xl border border-line bg-bg">
      <div className="grid gap-8 p-8 @2xl:grid-cols-[1fr_auto]">
        <p className="max-w-xs text-sm text-mute">Infrastructure for teams that would rather ship than babysit servers.</p>
        <div className="grid grid-cols-3 gap-8 text-sm">
          {columns.map(([h, links]) => (
            <div key={h}><div className="text-faint">{h}</div><ul className="mt-3 space-y-2">{links.map((l) => <li key={l}><a href="#" onClick={(e) => e.preventDefault()} className="text-mute hover:text-tx">{l}</a></li>)}</ul></div>
          ))}
        </div>
      </div>
      <div className="flex select-none justify-center border-t border-line px-4 pt-4" aria-hidden>
        {brand.split('').map((ch, i) => (
          <motion.span key={i} initial={{ y: '60%', opacity: 0 }} whileInView={{ y: '22%', opacity: 1 }} viewport={{ once: true }} transition={{ delay: i * 0.06, type: 'spring', stiffness: 160, damping: 18 }}
            className="bg-gradient-to-b from-tx to-transparent bg-clip-text text-[24cqw] font-semibold leading-none tracking-[-0.06em] text-transparent">{ch}</motion.span>
        ))}
      </div>
    </footer>
  )
}

'use client'

import { useState } from 'react'
import { motion, AnimatePresence } from 'motion/react'

const ENTRIES = [
  { v: '2.4.0', d: 'Sep 22', tag: 'Feature', t: 'Traffic map in the dashboard', b: ['Live arcs between edge locations', 'Filter by country and status code'] },
  { v: '2.3.2', d: 'Sep 15', tag: 'Fix', t: 'Faster cold starts', b: ['Median cold start down to 12 ms', 'Smaller runtime bundle'] },
  { v: '2.3.0', d: 'Sep 02', tag: 'Feature', t: 'Instant rollback', b: ['Roll back to any build in one click', 'Keeps environment variables in sync'] },
]
const TONE = { Feature: 'bg-acc/15 text-acc', Fix: 'bg-emerald-400/10 text-emerald-300' }

// Block: product changelog on a timeline. Entries expand in place.
export default function ChangelogFeed({ entries = ENTRIES }) {
  const [open, setOpen] = useState(0)
  return (
    <section className="@container w-full rounded-2xl border border-line bg-bg p-6">
      <h2 className="text-xl font-semibold tracking-tight text-tx">Changelog</h2>
      <ol className="relative mt-6 border-l border-line pl-6">
        {entries.map((e, i) => (
          <li key={e.v} className="relative pb-6 last:pb-0">
            <motion.span animate={{ scale: open === i ? 1.3 : 1, backgroundColor: open === i ? 'var(--acc)' : 'var(--line2)' }} className="absolute -left-[29px] top-1.5 size-2.5 rounded-full ring-4 ring-bg" />
            <button type="button" onClick={() => setOpen(open === i ? -1 : i)} aria-expanded={open === i} className="w-full text-left">
              <div className="flex flex-wrap items-center gap-2 text-xs"><span className="font-mono text-tx">v{e.v}</span><span className="text-faint">{e.d}</span><span className={`rounded-full px-2 py-0.5 text-[10px] ${TONE[e.tag] || 'bg-line text-mute'}`}>{e.tag}</span></div>
              <div className="mt-1 text-[15px] text-tx">{e.t}</div>
            </button>
            <AnimatePresence initial={false}>
              {open === i && (
                <motion.ul initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }} transition={{ type: 'spring', stiffness: 300, damping: 32 }} className="overflow-hidden">
                  {e.b.map((b) => <li key={b} className="mt-2 flex gap-2 text-sm text-mute"><span className="text-faint">-</span>{b}</li>)}
                </motion.ul>
              )}
            </AnimatePresence>
          </li>
        ))}
      </ol>
    </section>
  )
}

'use client'

import { useState } from 'react'
import { motion, AnimatePresence } from 'motion/react'

const valid = (v) => /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(v)

// Block: magic-link sign-in. Validates as you type, shakes on a bad address, confirms with a sent state.
/** @param {{ product?: any, onSubmit?: any }} props */
export default function SignInCard({ product = 'Acme', onSubmit = undefined }) {
  const [email, setEmail] = useState('')
  const [state, setState] = useState('idle')
  const [shake, setShake] = useState(0)
  const submit = async (e) => {
    e.preventDefault()
    if (!valid(email)) { setShake((n) => n + 1); return }
    setState('sending')
    try { await (onSubmit ? onSubmit(email) : new Promise((r) => setTimeout(r, 900))); setState('sent') } catch { setState('error') }
  }
  return (
    <section className="@container grid w-full place-items-center rounded-2xl border border-line bg-bg p-6 @2xl:p-12">
      <div className="w-full max-w-sm rounded-2xl border border-line bg-panel p-6">
        <AnimatePresence mode="wait" initial={false}>
          {state === 'sent' ? (
            <motion.div key="sent" initial={{ opacity: 0, scale: 0.96 }} animate={{ opacity: 1, scale: 1 }} exit={{ opacity: 0 }} className="py-4 text-center">
              <motion.svg viewBox="0 0 24 24" className="mx-auto size-10 text-emerald-400" fill="none" stroke="currentColor" strokeWidth="1.8"><motion.path d="M4 12.5 9.5 18 20 6" initial={{ pathLength: 0 }} animate={{ pathLength: 1 }} transition={{ duration: 0.5 }} /></motion.svg>
              <h3 className="mt-4 text-base font-medium text-tx">Check your inbox</h3>
              <p className="mt-1 text-sm text-mute">We sent a sign-in link to <span className="text-tx">{email}</span></p>
              <button type="button" onClick={() => setState('idle')} className="mt-5 text-xs text-mute underline underline-offset-4 hover:text-tx">Use a different email</button>
            </motion.div>
          ) : (
            <motion.form key="form" onSubmit={submit} noValidate initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}>
              <h3 className="text-lg font-medium tracking-tight text-tx">Sign in to {product}</h3>
              <p className="mt-1 text-sm text-mute">No password. We will email you a link.</p>
              <button type="button" className="mt-5 flex h-10 w-full items-center justify-center gap-2 rounded-lg border border-line2 bg-bg text-sm text-tx hover:bg-panel2">
                <svg viewBox="0 0 24 24" className="size-4" fill="currentColor"><path d="M12 .5a11.5 11.5 0 0 0-3.6 22.4c.6.1.8-.3.8-.6v-2c-3.2.7-3.9-1.5-3.9-1.5-.5-1.3-1.3-1.7-1.3-1.7-1-.7.1-.7.1-.7 1.2.1 1.8 1.2 1.8 1.2 1 1.8 2.8 1.3 3.5 1 .1-.8.4-1.3.7-1.6-2.6-.3-5.3-1.3-5.3-5.7 0-1.3.5-2.3 1.2-3.1-.1-.3-.5-1.5.1-3.1 0 0 1-.3 3.2 1.2a11 11 0 0 1 5.8 0C17.3 4.8 18.3 5.1 18.3 5.1c.6 1.6.2 2.8.1 3.1.8.8 1.2 1.9 1.2 3.1 0 4.4-2.7 5.4-5.3 5.7.4.4.8 1.1.8 2.2v3.2c0 .3.2.7.8.6A11.5 11.5 0 0 0 12 .5Z" /></svg>
                Continue with GitHub
              </button>
              <div className="my-4 flex items-center gap-3 text-[11px] text-faint"><span className="h-px flex-1 bg-line" />or<span className="h-px flex-1 bg-line" /></div>
              <motion.label key={shake} animate={shake ? { x: [0, -8, 8, -5, 5, 0] } : {}} transition={{ duration: 0.4 }}
                className={`flex h-10 items-center rounded-lg border bg-bg px-3 transition-colors focus-within:border-acc/70 ${shake && !valid(email) ? 'border-rose-500/60' : 'border-line2'}`}>
