/** @param {{ label?: any, duration?: any, onConfirm?: any }} props */
export default function HoldToConfirm({ label = 'Hold to delete', duration = 1.4, onConfirm = undefined }) {
  const p = useMotionValue(0)
  const ctl = useRef(null)
  const [done, setDone] = useState(false)

  const start = () => {
    if (done) return
    ctl.current = animate(p, 1, {
      duration: duration * (1 - p.get()), ease: 'linear',
      onComplete: () => { setDone(true); onConfirm?.(); setTimeout(() => { setDone(false); p.set(0) }, 1800) },
    })
  }
  const stop = () => {
    if (done) return
    ctl.current?.stop()
    animate(p, 0, { type: 'spring', stiffness: 300, damping: 26 })
  }

  return (
    <motion.button
      onPointerDown={start} onPointerUp={stop} onPointerLeave={stop}
      whileTap={{ scale: 0.97 }}
      className="relative flex h-12 select-none items-center gap-3 overflow-hidden rounded-xl border border-line2 bg-panel pl-3 pr-5 text-sm text-tx"
    >
      <motion.span style={{ scaleX: p }} className="absolute inset-0 origin-left bg-red-500/10" />
      <span className="relative grid size-7 place-items-center">
        <svg viewBox="0 0 28 28" className="absolute inset-0 -rotate-90">
          <circle cx="14" cy="14" r="12" fill="none" stroke="var(--line2)" strokeWidth="2" />
          <motion.circle cx="14" cy="14" r="12" fill="none" stroke="#ef4444" strokeWidth="2" strokeLinecap="round" style={{ pathLength: p }} />
        </svg>
        <AnimatePresence mode="wait">
          {done ? (
            <motion.svg key="c" viewBox="0 0 24 24" className="size-4 text-red-400" initial={{ scale: 0 }} animate={{ scale: 1 }} transition={{ type: 'spring', stiffness: 500, damping: 18 }}>
              <motion.path d="M5 12l5 5 9-10" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" initial={{ pathLength: 0 }} animate={{ pathLength: 1 }} />
            </motion.svg>
          ) : (
            <motion.span key="d" exit={{ scale: 0 }} className="size-1.5 rounded-full bg-red-400" />
          )}
        </AnimatePresence>
      </span>
      <span className="relative">{done ? 'Account deleted' : label}</span>
    </motion.button>
  )
}

'use client'

import { useCallback, useEffect, useState } from 'react'
import { motion, AnimatePresence } from 'motion/react'

// Default people are initials only, so the component makes no network requests out of the box.
// Pass `people` with your own `src` photos (https, a path on your site, or a data:image URL).
const POOL = [
  { id: 'p1', initials: 'AK', hue: '#d8b27a' },
  { id: 'p2', initials: 'MS', hue: '#8fb996' },
  { id: 'p3', initials: 'RJ', hue: '#e8a2b4' },
  { id: 'p4', initials: 'PN', hue: '#b9b4ab' },
  { id: 'p5', initials: 'DV', hue: '#c9a2e0' },
  { id: 'p6', initials: 'SL', hue: '#e0a184' },
  { id: 'p7', initials: 'TK', hue: '#c8a27a' },
  { id: 'p8', initials: 'IB', hue: '#b5c48a' },
  { id: 'p9', initials: 'AR', hue: '#d69bb8' },
  { id: 'p10', initials: 'NK', hue: '#93b8a4' },
  { id: 'p11', initials: 'SP', hue: '#c8a883' },
  { id: 'p12', initials: 'RM', hue: '#a1a1a6' },
]

const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/

// Only same-site paths, https and inline images are used as photos. Anything else (javascript:, http:, other schemes) falls back to initials.
const safeSrc = (src) => (typeof src === 'string' && /^(https:\/\/|\/(?!\/)|\.{1,2}\/|data:image\/(png|jpe?g|gif|webp|avif);)/i.test(src.trim()) ? src.trim() : '')

function Avatar({ person, first }) {
  const src = safeSrc(person.src)
  const [ok, setOk] = useState(true)
  const [loaded, setLoaded] = useState(false)
  return (
    <motion.div
      layout
      initial={{ opacity: 0, scale: 0.4, x: -16 }}
      animate={{ opacity: 1, scale: 1, x: 0 }}
      transition={{ type: 'spring', stiffness: 160, damping: 22 }}
      whileHover={{ scale: 1.12, transition: { type: 'spring', stiffness: 400, damping: 22 } }}
      className="relative grid size-9 shrink-0 place-items-center overflow-hidden rounded-full border-2 border-bg text-[11px] font-semibold text-white"
      style={{ background: person.hue || '#8a8a93', marginLeft: first ? 0 : -8 }}
    >
      {person.initials}
      {src && ok && (
        <img
          src={src}
          referrerPolicy="no-referrer"
          alt=""
          loading="lazy"
          onLoad={() => setLoaded(true)}
          onError={() => setOk(false)}
          className="absolute inset-0 size-full rounded-full object-cover transition-opacity duration-300"
          style={{ opacity: loaded ? 1 : 0 }}
        />
      )}
    </motion.div>
  )
}

/** @param {{ placeholder?: any, buttonLabel?: any, successLabel?: any, retryLabel?: any, errorLabel?: any, count?: any, countLabel?: any, people?: any, visible?: any, autoJoin?: any, autoJoinInterval?: any, onSubmit?: any }} props */
export default function WaitlistForm({
  placeholder = 'Enter your email',
  buttonLabel = 'Join Waitlist',
  successLabel = "You're in!",
  retryLabel = 'Try again',
  errorLabel = 'Could not join right now. Please try again.',
  count = 32,
  countLabel = 'People joined today',
  people = POOL,
  visible = 5,
  autoJoin = false,
  autoJoinInterval = 4800,
  onSubmit = undefined,
}) {
  const [email, setEmail] = useState('')
  const [state, setState] = useState('idle') // idle | sending | done | failed
  const [shake, setShake] = useState(false)
  const [joined, setJoined] = useState(0)
  // Window start index into people; the visible stack is derived, so a face can never repeat.
  const [start, setStart] = useState(0)
  const done = state === 'done'
  const n = people.length
  const heads = n ? Array.from({ length: Math.min(visible, n) }, (_, i) => people[(start + i) % n]) : []

  const pushOne = useCallback(() => {
    setJoined((j) => j + 1)
    if (n) setStart((s) => (s - 1 + n) % n)
  }, [n])

  // Demo-only conveyor: off by default so production counts stay real. Enable with autoJoin.
  useEffect(() => {
    if (!autoJoin || !n) return
    const t = setInterval(pushOne, autoJoinInterval)
    return () => clearInterval(t)
  }, [autoJoin, autoJoinInterval, n, pushOne])

  const submit = async (e) => {
    e.preventDefault()
    if (state === 'sending' || done) return
    if (!EMAIL.test(email.trim())) {
      setShake(true)
      setTimeout(() => setShake(false), 450)
      return
    }
    setState('sending')
    try {
      await onSubmit?.(email.trim())
      setState('done')
      pushOne()
    } catch {
      setState('failed')
    }
  }

  return (
    <div className="flex w-full max-w-md flex-col gap-4">
      <form onSubmit={submit} className="flex flex-col gap-3 sm:flex-row">
        <motion.input
          type="email"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          placeholder={placeholder}
          animate={shake || state === 'failed' ? { x: [0, -8, 8, -5, 5, 0] } : { x: 0 }}
          transition={{ duration: 0.4 }}
          className={`h-14 w-full flex-1 rounded-2xl border bg-panel2 px-5 text-sm text-tx outline-none transition-colors placeholder:text-faint ${shake || state === 'failed' ? 'border-red-400' : 'border-line focus:border-line2'}`}
        />
        <motion.button
          type="submit"
          whileTap={{ scale: 0.97 }}
          className="relative h-14 shrink-0 rounded-2xl bg-tx px-7 text-sm font-medium text-bg"
        >
          <AnimatePresence mode="wait" initial={false}>
            <motion.span
              key={state}
              initial={{ y: 12, opacity: 0 }}
              animate={{ y: 0, opacity: 1 }}
              exit={{ y: -12, opacity: 0 }}
              transition={{ duration: 0.18 }}
              className="flex items-center justify-center gap-2"
            >
              {done ? (
                <>
                  <svg viewBox="0 0 24 24" className="size-4">
                    <motion.path d="M5 12l5 5 9-10" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" initial={{ pathLength: 0 }} animate={{ pathLength: 1 }} transition={{ duration: 0.35, delay: 0.05 }} />
                  </svg>
                  {successLabel}
                </>
              ) : state === 'sending' ? (
                <motion.span animate={{ rotate: 360 }} transition={{ repeat: Infinity, ease: 'linear', duration: 0.8 }} className="size-4 rounded-full border-2 border-bg/30 border-t-bg" />
              ) : state === 'failed' ? (
                retryLabel
              ) : (
                buttonLabel
              )}
            </motion.span>
          </AnimatePresence>
        </motion.button>
      </form>
      <AnimatePresence initial={false}>
        {state === 'failed' && (
          <motion.p initial={{ opacity: 0, y: -4 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0 }} className="-mt-1 text-xs text-red-400">
            {errorLabel}
          </motion.p>
        )}
      </AnimatePresence>
      <div className="flex items-center gap-4">
        {heads.length > 0 && (
          <div className="flex">
            {heads.map((p, i) => <Avatar key={p.id ?? p.initials} person={p} first={i === 0} />)}
          </div>
        )}
        <div className="flex items-center text-xs">
          <span className="relative z-10 rounded-full bg-tx px-2.5 py-1 font-semibold text-bg">
            <AnimatePresence mode="popLayout" initial={false}>
              <motion.span key={count + joined} initial={{ y: 10, opacity: 0 }} animate={{ y: 0, opacity: 1 }} exit={{ y: -10, opacity: 0 }} transition={{ type: 'spring', stiffness: 260, damping: 30 }} className="inline-block tabular-nums">
                {count + joined}
              </motion.span>
            </AnimatePresence>
          </span>
          <span className="-ml-2 rounded-full border border-line bg-panel2 py-1 pl-4 pr-3 text-mute">{countLabel}</span>
        </div>
      </div>
    </div>
  )
}

'use client'

import { useEffect, useId, useRef, useState } from 'react'
import { AnimatePresence, motion, useReducedMotion, useSpring, useTransform } from 'motion/react'

const spring = { type: 'spring', stiffness: 420, damping: 32 }

// Simulated upload: eases to 100% over ~1.6s with requestAnimationFrame, so the ring never steps.
function fakeUpload(_file, onProgress) {
  return new Promise((resolve) => {
    const start = performance.now(), ms = 1600
    const tick = (now) => {
      const t = Math.min(1, (now - start) / ms)
      onProgress(1 - (1 - t) ** 3)
      if (t < 1) requestAnimationFrame(tick); else resolve()
    }
    requestAnimationFrame(tick)
  })
}

/** @param {{ initialSrc?: any, size?: any, maxSizeMB?: any, onUpload?: any, onChange?: any, demoSrc?: any, name?: any }} props */
export default function AvatarUpload({
  initialSrc = '',
  size = 112,
  maxSizeMB = 5,
  onUpload = undefined,
  onChange = undefined,
  demoSrc = '',
  name = 'Profile photo',
}) {
  const [src, setSrc] = useState(initialSrc)
  const [status, setStatus] = useState(initialSrc ? 'done' : 'empty') // empty | uploading | done | error
  const [error, setError] = useState('')
  const [drag, setDrag] = useState(false)
  const input = useRef(null)
  const urlRef = useRef('')
  const run = useRef(0)
  const id = useId()
  const reduce = useReducedMotion()
  const progress = useSpring(0, { stiffness: 140, damping: 26 })
  const dash = useTransform(progress, (p) => Math.max(0, Math.min(1, p)))

  const R = size / 2 + 6, C = size + 12

  const release = () => { if (urlRef.current) { URL.revokeObjectURL(urlRef.current); urlRef.current = '' } }
  useEffect(() => release, [])

  const start = async (file, preview) => {
    const token = ++run.current
    setError(''); setSrc(preview); setStatus('uploading'); progress.jump(0)
    try {
      await (onUpload || fakeUpload)(file, (p) => token === run.current && progress.set(p))
      if (token !== run.current) return
      progress.set(1); setStatus('done'); onChange?.(file)
    } catch (e) {
      if (token !== run.current) return
      setStatus('error'); setError(e?.message || 'Upload failed. Try again.')
    }
  }

  const take = (file) => {
    if (!file) return
    if (!file.type?.startsWith('image/')) { setError('Choose a JPG, PNG or WebP image.'); return }
    if (file.size > maxSizeMB * 1e6) { setError(`That photo is over ${maxSizeMB} MB.`); return }
    release()
    urlRef.current = URL.createObjectURL(file)
    start(file, urlRef.current)
  }

  const remove = () => {
    run.current++; release(); progress.jump(0)
    setSrc(''); setStatus('empty'); setError(''); onChange?.(null)
  }

  // Site demo only: walks through one upload with a local image so the preview is alive.
  useEffect(() => {
    if (!demoSrc) return
    const t = setTimeout(() => start(null, demoSrc), 900)
    return () => clearTimeout(t)
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [demoSrc])

  const pick = () => input.current?.click()
  const busy = status === 'uploading'

  return (
    <div className="flex w-[300px] max-w-full flex-col items-center text-center">
      <motion.div
        className="relative"
        style={{ width: C, height: C }}
        animate={{ scale: drag ? 1.04 : 1 }}
        transition={spring}
        onDragEnter={(e) => { e.preventDefault(); setDrag(true) }}
        onDragOver={(e) => e.preventDefault()}
        onDragLeave={() => setDrag(false)}
        onDrop={(e) => { e.preventDefault(); setDrag(false); take(e.dataTransfer.files?.[0]) }}
      >
        <svg className="absolute inset-0 -rotate-90" width={C} height={C} viewBox={`0 0 ${C} ${C}`} aria-hidden>
          <circle cx={C / 2} cy={C / 2} r={R - 2} fill="none" stroke="var(--line2)" strokeWidth="2" strokeDasharray={src ? '0' : '3 5'} />
          <motion.circle cx={C / 2} cy={C / 2} r={R - 2} fill="none" stroke="var(--tx)" strokeWidth="2.5" strokeLinecap="round"
            style={{ pathLength: dash }} animate={{ opacity: busy ? 1 : 0 }} transition={{ duration: 0.3 }} />
        </svg>

        <button
          type="button"
          onClick={pick}
          disabled={busy}
          aria-describedby={`${id}-hint`}
          aria-label={src ? 'Replace profile photo' : 'Upload profile photo'}
          className="group absolute left-1.5 top-1.5 overflow-hidden rounded-full bg-panel2 outline-none ring-offset-2 ring-offset-bg focus-visible:ring-2 focus-visible:ring-tx"
          style={{ width: size, height: size }}
        >
          <AnimatePresence initial={false} mode="popLayout">
            {src ? (
              <motion.img key={src} src={src} alt={name} draggable={false} className="size-full object-cover"
                initial={reduce ? false : { opacity: 0, scale: 1.12, filter: 'blur(8px)' }}
                animate={{ opacity: busy ? 0.55 : 1, scale: 1, filter: 'blur(0px)' }}
                exit={{ opacity: 0 }} transition={{ duration: 0.45, ease: [0.22, 1, 0.36, 1] }} />
            ) : (
              <motion.span key="empty" className="grid size-full place-items-center text-faint" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}>
                <svg viewBox="0 0 24 24" className="size-9" fill="none" stroke="currentColor" strokeWidth="1.5" aria-hidden><circle cx="12" cy="8.5" r="3.5" /><path d="M5 19.5c1.4-3 4-4.5 7-4.5s5.6 1.5 7 4.5" /></svg>
              </motion.span>
            )}
          </AnimatePresence>
          {!busy && (
            <span className="absolute inset-0 grid place-items-center bg-black/45 text-[12px] font-medium text-white opacity-0 transition-opacity duration-200 group-hover:opacity-100 group-focus-visible:opacity-100">
              {src ? 'Replace' : 'Upload'}
            </span>
          )}
        </button>

        <AnimatePresence>
          {status === 'done' && src && (
            <motion.span key="ok" className="absolute bottom-2 right-2 grid size-7 place-items-center rounded-full border-2 border-bg bg-tx text-bg"
              initial={{ scale: 0 }} animate={{ scale: 1 }} exit={{ scale: 0 }} transition={{ type: 'spring', stiffness: 520, damping: 22 }} aria-hidden>
              <svg viewBox="0 0 24 24" className="size-3.5" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><motion.path d="M5 12.5l4.5 4.5L19 7.5" initial={{ pathLength: 0 }} animate={{ pathLength: 1 }} transition={{ delay: 0.12, duration: 0.3 }} /></svg>
            </motion.span>
          )}
        </AnimatePresence>
      </motion.div>

      <input ref={input} type="file" accept="image/*" className="sr-only" tabIndex={-1} aria-hidden onChange={(e) => { take(e.target.files?.[0]); e.target.value = '' }} />

      <div className="mt-4 text-[15px] font-medium text-tx">{name}</div>
      <div id={`${id}-hint`} className="mt-1 h-5 text-[13px]" aria-live="polite">
        <AnimatePresence mode="wait" initial={false}>
          <motion.span key={error || status} className={error ? 'text-rose-500' : 'text-mute'} initial={{ opacity: 0, y: 4 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -4 }} transition={{ duration: 0.18 }}>
            {error || (busy ? 'Uploading…' : status === 'done' ? 'Saved' : `Drop or click. JPG, PNG, up to ${maxSizeMB} MB.`)}
          </motion.span>
        </AnimatePresence>
      </div>

      <div className="mt-4 flex gap-2">
        <button type="button" onClick={pick} disabled={busy} className="h-9 rounded-full bg-tx px-4 text-[13px] font-medium text-bg transition-transform active:scale-95 disabled:opacity-40">
          {src ? 'Replace' : 'Choose photo'}
        </button>
        <AnimatePresence initial={false}>
          {src && !busy && (
            <motion.button key="rm" type="button" onClick={remove} initial={{ opacity: 0, width: 0 }} animate={{ opacity: 1, width: 'auto' }} exit={{ opacity: 0, width: 0 }} transition={spring}
              className="h-9 overflow-hidden whitespace-nowrap rounded-full border border-line2 px-4 text-[13px] text-mute hover:text-tx">
              Remove
            </motion.button>
          )}
        </AnimatePresence>
      </div>
    </div>
  )
}

'use client'

import { useCallback, useEffect, useRef, useState } from 'react'
import { AnimatePresence, motion } from 'motion/react'

const RED = '#e5484d'

const EXT_COLORS = {
  pdf: '#e5484d',
  png: '#c8a27a',
  jpg: '#c8a27a',
  jpeg: '#c8a27a',
  gif: '#c8a27a',
  svg: '#c8a27a',
  xlsx: '#30a46c',
  xls: '#30a46c',
  csv: '#30a46c',
  doc: '#a1a1a6',
  docx: '#a1a1a6',
  pptx: '#e5793c',
  mp4: '#d6409f',
  mov: '#d6409f',
  mp3: '#b07fd6',
  zip: '#8b8b96',
  txt: '#8b8b96',
  json: '#8b8b96',
}
const extOf = (name) => (name.includes('.') ? name.split('.').pop().toLowerCase() : 'file')
const extColor = (ext) => EXT_COLORS[ext] || '#8b8b96'

let uid = 0
// The unit follows the total ("120 of 980 KB", "1.2 of 4.2 MB") so a pair never mixes units.
const fmtSize = (b, total = b) => (total < 1e6 ? `${Math.max(b > 0 ? 1 : 0, Math.round(b / 1e3))}` : (b / 1e6).toFixed(1))
const unit = (total) => (total < 1e6 ? 'KB' : 'MB')
// Deterministic per-name upload rate so the demo tells the same story every load.
const rateOf = (name) => {
  let h = 0
  for (let i = 0; i < name.length; i++) h = (h * 31 + name.charCodeAt(i)) >>> 0
  return 0.14 + (h % 100) / 1000 // 4.5-7s per file
}

