      telegram: `https://t.me/share/url?url=${q(link)}&text=${q(text)}`,
      x: `https://twitter.com/intent/tweet?url=${q(link)}&text=${q(text)}`,
      mail: `mailto:?subject=${q(title)}&body=${q(`${message.trim() ? `${message.trim()}\n\n` : ''}${link}`)}`,
