export function hexToRgb(hex: string | undefined, fallback: RGB): RGB {
  const s = typeof hex === 'string' ? hex.trim().replace(/^#([0-9a-f])([0-9a-f])([0-9a-f])$/i, '#$1$1$2$2$3$3') : ''
