      g.uniform1f(U('uAmp'), Math.min(2, Math.max(0, num(p.intensity, 1)))); g.uniform1f(U('uScale'), Math.max(0.05, num(p.scale, 1)))
      for (const [name, v] of Object.entries(p.uniforms || {})) { const l = U(name); if (l) g.uniform1f(l, num(v, 0)) }
