  /** Time multiplier. 0 freezes the frame. */
  speed?: number
  /** How strongly the pattern shows, 0 to 2. */
  intensity?: number
  /** Zoom of the pattern. Above 1 is finer, below 1 is larger. */
  scale?: number
  /** React to the pointer. */
  interactive?: boolean
